const ExoFacilityUI=(()=>{
 const F=()=>ExoFacilities.active;
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const call=(name,...args)=>esc('Exo.'+name+'('+args.map(value=>JSON.stringify(value)).join(',')+')');
 function status(u){const a=F(),el=document.getElementById('hud-facility');if(!el)return;el.hidden=!a;if(!a)return;const p=ExoFacilities.progress(a.structure),room=ExoFacilities.roomAt(u),text=`${a.name} · B${a.level+1}/B3\n${room?.name||'连接廊道'} · 已探索 ${p.visited.length}/39 间\n${ExoFacilities.objective()}`;if(el.textContent!==text)el.textContent=text;}
 function record(a,index){
  const clue=typeof ExoFieldClues!=='undefined'?ExoFieldClues.get(a.structure,index):null;if(clue)return {title:clue.object};
  if(typeof ExoLore!=='undefined'&&ExoLore.siteRecord)return ExoLore.siteRecord(a.structure,index);
  const node=a.plan.decks[Math.floor(index/2)]?.nodes.find(n=>n.kind==='log'&&n.index===index);
  return {title:node?.name||'现场记录 '+(index+1)};
 }
 function routeTo(a,u,node){
  const rooms=new Map(a.deck.rooms.map(r=>[r.id,r])),current=ExoFacilities.roomAt(u),start=rooms.get(current?.id)||a.deck.rooms.reduce((best,r)=>Math.hypot(r.x-u.x,r.y-u.y)<Math.hypot(best.x-u.x,best.y-u.y)?r:best,a.deck.rooms[0]),end=rooms.get(node.room);
  if(!start||!end)return null;
  const edges=new Map([...rooms.keys()].map(id=>[id,[]]));
  // Never turn a stale/cloned reference into an invented connection. The
  // physical deck and the highlighted route share the exact room objects.
  for(const link of a.deck.links){if(rooms.get(link.a?.id)!==link.a||rooms.get(link.b?.id)!==link.b)continue;edges.get(link.a.id).push(link.b.id);edges.get(link.b.id).push(link.a.id);}
  const previous=new Map([[start.id,null]]),queue=[start.id];
  for(let i=0;i<queue.length&&!previous.has(end.id);i++)for(const next of edges.get(queue[i]))if(!previous.has(next)){previous.set(next,queue[i]);queue.push(next);}
  if(!previous.has(end.id))return null;
  const ids=[];for(let id=end.id;id!==null;id=previous.get(id))ids.push(id);ids.reverse();
  return {rooms:ids.map(id=>rooms.get(id)),points:[u,...ids.map(id=>rooms.get(id)),node]};
 }
 function atlas(u,evidenceIndex=null){
  const a=F();if(!a)return '<div class="fc-panel"><p>进入建筑后，可以在这里查看楼层与现场记录。</p></div>';
  const d=a.deck,p=ExoFacilities.progress(a.structure),sx=x=>20+x/d.width*660,sy=y=>17.5+y/d.height*430,done=n=>ExoFacilities.done(n),icons={relay:'电',cache:'箱',log:'物',next:'↓',back:'↑',exit:'↗',vault:'◆'},program=a.plan.program;
  const validTarget=Number.isInteger(evidenceIndex)&&evidenceIndex>=0&&evidenceIndex<=6,coreTarget=evidenceIndex===6,targetFloor=validTarget?(coreTarget?2:Math.floor(evidenceIndex/2)):null,desired=validTarget?a.plan.decks[targetFloor]?.nodes.find(n=>coreTarget?n.kind==='vault':n.kind==='log'&&n.index===evidenceIndex):null;
  const target=desired?(targetFloor===a.level?desired:d.nodes.find(n=>n.kind===(targetFloor>a.level?'next':'back'))):null,route=target?routeTo(a,u,target):null,targetRecord=desired?(coreTarget?{title:desired.name}:record(a,evidenceIndex)):null,targetRoom=desired?a.plan.decks[targetFloor].rooms.find(r=>r.id===desired.room):null;
  const routeHeading=desired?`目标：B${targetFloor+1} · ${targetRoom?.name||'物件旁'}`:'';
  const routeHelp=desired?(targetFloor===a.level?(coreTarget?'沿琥珀色路线前往封存核心，走近后按 E 交接。回收前需要接通三层全部六处供电终端，并清理附近守卫。':'沿琥珀色路线到达物件旁，走近后按 E 调查。'):`先沿琥珀色路线到达「${target?.name||'升降舱'}」，再前往 B${targetFloor+1}。${targetFloor>a.level&&!ExoFacilities.powered(a.level)?'当前升降舱尚未供电；先接通本层两处供电终端。':''}`):'';
  const navigation=desired?`<div class="fc-note facility-evidence-route" data-evidence-index="${evidenceIndex}" data-target-floor="${targetFloor}"><b>${esc(routeHeading)}</b><p>${esc((coreTarget?p.vault:p.logs.includes(evidenceIndex))?'已回收：':coreTarget?'待回收核心：':'待调查载体：')}${esc(targetRecord.title)}</p><p>${esc(route?routeHelp:'当前位置与目标之间没有可确认的通道，请先返回已标注的房间。')}</p>${route?`<p>本层经过：${route.rooms.map(r=>esc(String(r.id+1).padStart(2,'0')+' '+r.name)).join(' → ')}</p>`:''}<small>地图只标出路径，不会自动驾驶。</small></div>`:'';
  const found=[...new Set(p.logs)].filter(i=>Number.isInteger(i)&&i>=0&&i<6).sort((a,b)=>a-b);
  return `<div class="fc-panel facility-atlas"><div class="fc-eyebrow">地下探索 / 当前 B${a.level+1} · ${esc(d.title||program?.decks?.[a.level]||'设施楼层')}</div><h2>${esc(a.name)}</h2>${desired?`<p class="facility-route-destination"><b>${esc(routeHeading)}</b> · ${esc(targetRecord.title)}</p>`:''}<svg viewBox="0 0 700 465" role="img" aria-label="当前建筑 B${a.level+1} 楼层地图：房间、通道、供电终端与升降舱"><rect width="700" height="465" fill="#081b27"/>${d.links.map(t=>`<path d="M${sx(t.a.x)} ${sy(t.a.y)} L${sx(t.b.x)} ${sy(t.b.y)}" stroke="#315768" stroke-width="${t.w/(t.a.x===t.b.x?d.width/660:d.height/430)}" fill="none"/>`).join('')}${d.rooms.map(r=>{const visited=p.visited.includes(a.level*13+r.id),onRoute=route?.rooms.includes(r);return `<rect data-room-id="${r.id}" x="${sx(r.x-r.w/2)}" y="${sy(r.y-r.d/2)}" width="${r.w/d.width*660}" height="${r.d/d.height*430}" fill="${visited?'#286273':'#172f3d'}" stroke="${onRoute?'#c9a66c':visited?'#83e4e0':'#577b8d'}"/><text x="${sx(r.x)}" y="${sy(r.y)-12}" text-anchor="middle" font-size="10" fill="#d1e8ed">${r.id+1}</text>`;}).join('')}${route?`<polyline data-facility-route="${route.rooms.map(r=>r.id).join(',')}" points="${route.points.map(q=>sx(q.x)+','+sy(q.y)).join(' ')}" fill="none" stroke="#e0b77a" stroke-width="3" stroke-dasharray="6 4" stroke-linecap="round" stroke-linejoin="round"/>`:''}${d.nodes.map(n=>`<circle cx="${sx(n.x)}" cy="${sy(n.y)}" r="9" fill="${n===target?'#b88b48':done(n)?'#42685c':n.kind==='relay'?'#bc7a38':n.kind==='vault'?'#7b4d9e':'#254d67'}"/><text x="${sx(n.x)}" y="${sy(n.y)+3}" text-anchor="middle" font-size="9" fill="white">${done(n)?'✓':icons[n.kind]||'·'}</text>`).join('')}${target?`<circle data-route-target="${esc(target.id)}" cx="${sx(target.x)}" cy="${sy(target.y)}" r="14" fill="none" stroke="#e0b77a" stroke-width="2"/>`:''}<circle cx="${sx(u.x)}" cy="${sy(u.y)}" r="5" fill="white" stroke="#07121b" stroke-width="2"/></svg>${navigation}<details class="facility-building-details"><summary>建筑用途与探索进度</summary><p>${esc(program?.summary||'这座设施的设备、记录与道路仍保留着工作时的痕迹。')}</p><div class="fc-buttons"><button onclick="${call('openSiteStory',a.structure.id)}">这座建筑留下了什么 ↗</button><button onclick="${call('regionArchive',a.structure.sector,'interior')}">看看这座设施 ↗</button></div><p>地下共有三层。每层承担不同的工作；沿设备和通道寻找留下的痕迹，没有时间限制。</p><div class="facility-stats"><span>已探索 ${p.visited.length}/39 间</span><span>供电 ${p.relays.length}/6</span><span>物资 ${p.caches.length}/12</span><span>记录 ${p.logs.length}/6</span><span>${p.vault?'核心已回收':'核心待寻找'}</span></div></details><p class="facility-map-key">白点：你的位置 · 电：供电 · 箱：补给 · 物：可检查的物件 · 箭头：升降舱${route?' · 琥珀色虚线：本层调查路线':''}</p><p>${esc(ExoFacilities.objective())}。走近终端后按 E，或点击画面中的交互按钮。每层入口都能免费修复装甲。</p><div class="cave-room-index">${d.rooms.map(r=>`<span>${String(r.id+1).padStart(2,'0')} · ${esc(r.name)}</span>`).join('')}</div><details><summary>记在日记里的发现 · ${found.length}/6</summary>${found.length?found.map(i=>`<p><button onclick="${call('readRecord','log:'+a.structure.id+':'+i)}">B${Math.floor(i/2)+1} · ${esc(record(a,i).title)} ↗</button></p>`).join(''):'<p>工作间与档案室里留下了可检查的物件。靠近后按 E 打开、转动或收听。</p>'}</details><p class="facility-map-key">探索进度会自动保存在这个浏览器。下次回来，可以从已有进度继续。</p><div class="fc-buttons"><button class="primary" onclick="closeModal()">继续探索</button><button onclick="closeModal();Exo.evacuateFacility()">返回地表入口</button></div></div>`;
 }
 function directory(){return `<details class="facility-directory"><summary>可探索的建筑 · ${ExoWorld.structures.length} 座可探索</summary><p>每座建筑都有三层地下空间，藏着物资、记录和核心。选择下面的建筑可直接到达入口，再按 E 进入。</p><div class="atlas-camps">${ExoWorld.structures.map(s=>{const p=ExoFacilities.progress(s);return `<button onclick="closeModal();${call('visitFacility',s.id)}"><b>${esc(ExoFacilities.label(s))}</b><small>快速旅行至入口 · ${p.visited.length}/39 舱室${p.vault?' · 核心已回收':''}</small></button>`;}).join('')}</div></details>`;}
 function mini(g,u){const a=F();if(!a)return;const d=a.deck,x=v=>v/d.width*150,y=v=>v/d.height*100;g.clearRect(0,0,150,100);g.fillStyle='#081923';g.fillRect(0,0,150,100);g.lineWidth=3;g.strokeStyle='#345c6c';for(const t of d.links){g.beginPath();g.moveTo(x(t.a.x),y(t.a.y));g.lineTo(x(t.b.x),y(t.b.y));g.stroke();}for(const r of d.rooms){g.fillStyle='#406879';g.fillRect(x(r.x-r.w/2),y(r.y-r.d/2),r.w/d.width*150,r.d/d.height*100);}for(const n of d.nodes){g.fillStyle=ExoFacilities.done(n)?'#70d5b0':n.kind==='relay'?'#ffba70':'#a4d7ee';g.fillRect(x(n.x)-2,y(n.y)-2,4,4);}g.fillStyle='white';g.beginPath();g.arc(x(u.x),y(u.y),3,0,7);g.fill();}
 return {status,atlas,directory,mini};
})();
if(typeof module!=='undefined')module.exports=ExoFacilityUI;
